type Event struct {
  Data   string
  Cancel <-chan struct{}
}

func worker(id int, queue <-chan Event, done <-chan struct{}) {
  for {
    select {
    case e := <-queue:
      select {
      case <-e.Cancel:
        // canceled before processing
        continue
      default:
        process(e)
      }
    case <-done:
      return
    }
  }
}
